INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', '12', 'REF-00993', NULL, 1, 1, '[]', NULL, '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'FORWARD MINING NOT ATTEMPTED THIS PASS, and the reason is structural rather than a choice of effort: forward mining traces who CITES an anchor, which for this corpus runs through Crossref/Scopus citation graphs. A Japanese DPO web page carries no DOI and is not indexed by any citation database, so the forward graph does not reach it. The tractable forward route is a Japanese-language site search for organisations quoting the 義務基準が不十分 framing, which is a real unit of work and is NOT done here. Recorded as owed rather than passed.');
