 edition incorporating 2020 and 2024 amendments)', NULL, NULL, NULL, 'en', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://assets.publishing.service.gov.uk/media/66f6c5eec71e42688b65ee11/ADM__V2_with_2024_amendments.pdf', '2026-09-17', NULL, NULL, 6, 'code', 'GB', NULL, NULL, NULL, 'COMPLETE-STATUTORY', 'VERIFIED', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'gov-uk-assets', NULL, 1, NULL, 'Section 1, para 1.26(b)–(c) and Table 1 (Limits for ramp gradients), p.19–20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
