NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://dpi-japan.org/blog/workinggroup/traffic/barrier-free-crpd/', '2026-09-17', NULL, NULL, 1, 'co1', 'JP', 'DPI日本会議 (DPI-Japan) is the Japan national assembly of Disabled Peoples International — a cross-disability organisation OF disabled people, not a service provider for them, and DPI''s defining constitutional requirement is majority control by disabled people. The document is its own analysis of the CRPD Committee''s 2022 Concluding Observations on Japan and its resulting action plan, i.e. a DPO speaking in its own voice about the barrier-free standards its members live under. Evidenced in the retrieved bytes rather than inferred from venue (D-0178): the page is published under dpi-japan.org as the organisation''s own 要望・声明 (demands and statements) workstream output.', 'dpo_position_statement', NULL, 'COMPLETE', 'VERIFIED', 'NO-MATCH', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'retrieval-log', NULL, 1, NULL, '2．法律・制度・施策の改善ポイント（2）バリアフリー法の課題／義務基準が不十分', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-005', 'SW', 'P2', 'OPEN', NULL, NULL, 'R15 CANNOT BE DISCHARGED AGAINST research_code_leads: there is no update-code-lead verb. R15 requires a staged description to be re-described from the source on resolution and corrected if over-claimed. Batch 10 resolved lead 85 and PROVED part of its note false — lead 85 records that REF-00989 attributes 12分の1, 1/15 outdoors and 8分の1 to the Barrier-Free Law, and the retrieved law (REF-00990) contains 十五分の一 ZERO times; 1/15 is in a different instrument, MLIT Ordinance 114/2006, the voluntary 誘導基準 (REF-00991). db.py offers add-code-lead only; status stays REFERENCE-ONLY though the document is now RETRIEVED, and the note keeps asserting the false attribution to the next reader. update-locator moves a LOCATOR status, not a lead. The correction is currently recorded only in REF-00991 extraction notes, which a reader of the lead never sees. Coverage bug per CLAUDE.md section 4 — fix the writer, do not hand-write SQL.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (86, 'FR', 'Arrêté du 20 avril 2017 (accessibilité ERP neufs) — art. 2, profil en long', 'Article 2, II, 2° a) — plan incliné, pente', 'REFERENCE-ONLY', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000034485459', 'RETRIEVAL FAILURE, NOT ABSENCE, and deliberately holding no values (2026-08-12 REFERENCE-ONLY ruling). Légifrance answers HTTP 403 to automated retrieval on every route tried — /loda/id/, /jorf/article_jo/, /jorf/id/ and /download/pdf — with a browser User-Agent set; persisted 403 artefacts ecc3d03788c5d0ad and 4ddca3bcc61e5d52 are the evidence. The ministry carrier accessibilite-batiment.fr returns 200 but serves a byte-identical JS shell for every section (sha e6fbf3f3c030e5c1), so it carries no clause text either. The document is freely published and correctly identified; only the machine route is blocked, so a session with a browser or with PISTE API credentials closes this in one step. Values were SEEN through a reader tool and are NOT recorded here, because a figure the corpus cannot check against persisted bytes is the 2026-08-19 shape.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (43, 'accessible-circulation-geometry', 'JP', 'ja', 6, 'code', 'intrinsic', '高齢者、障害者等の移動等の円滑化の促進に関する法律 建築物移動等円滑化基準 傾斜路 勾配 e-Gov', NULL, 'web', 'scoping', NULL, 9, 9, 2, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'PRIOR PARTLY FALSIFIED, and the falsification is the result. Two of the three figures are confirmed IN THIS INSTRUMENT: Cabinet Order 379/2006 Art.19(2)(iv)ro and (vii)ni(2) both read 勾配は、十二分の一を超えないこと。ただし、高さが十六センチメートル以下のものにあっては、八分の一を超えないこと。 The third is NOT: 十五分の一 occurs ZERO times in the whole Cabinet Order. It was located instead in a DIFFERENT instrument retrieved in the same pass — MLIT Ordinance 114/2006 (the 誘導基準 / guideline standard), Art.11(1)(vi)ro, 勾配は、十五分の一を超えないこと, applying to 敷地内の通路 (paths within the site). So REF-00989 attributes to one law three figures that come from two instruments of DIFFERENT LEGAL FORCE: 1/12 and 1/8 are the mandatory 建築物移動等円滑化基準; 1/15 is the enhanced standard buildings meet voluntarily for certification. REF-00989 characterises 1/15 as the outdoor figure; the domain is roughly right (site paths) but the legal strength is not — nothing requires 1/15. Prior also CORRECT that no basis is stated: neither instrument gives any warrant, derivation or citation for any figure. Both admitted REF-00990 (Cabinet Order) and REF-00991 (Ordinance). Payloads persisted: retrieval-log manifest sha256 6ac7f09b… and edd9f6fc…, both HTTP 200 from the e-Gov API.', 0, 'research_code_leads 85, and it is a falsifiable row. The lead records that REF-00989 attributes three figures to this law — 12分の1, 1/15 outdoors, and 8分の１ for rises of 16cm or less — and that the law itself was never retrieved, so none was copied in (rule 5). Japanese law is published in full on e-Gov, so I expect the clause text itself. Prediction: all three figures are confirmed and no basis is stated for any of them. If they are not confirmed, the corpus has been holding a lived-experience assessment of a legal figure that is not what the law says, which is a larger finding than the value.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (44, 'accessible-circulation-geometry', 'FR', 'fr', 6, 'code', 'intrinsic', 'arrêté accessibilité ERP pente rampe pourcentage Légifrance texte consolidé', NULL, 'web', 'scoping', NULL, 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'R14 DIAGNOSIS: RETRIEVAL FAILURE — not absence, not wrong index, not query shape. The document was located on the first query and is the right one (Arrêté du 20 avril 2017, ERP neufs). Légifrance returns HTTP 403 to automated retrieval on every route tried: /loda/id/, /jorf/article_jo/, /jorf/id/ and the /download/pdf endpoint, with a browser User-Agent set. Persisted as evidence of the attempt: artefacts ecc3d03788c5d0ad.html and 4ddca3bcc61e5d52.html, both 403. The ministry carrier accessibilite-batiment.fr returns 200 but is JS-driven — /dispositions-generales/ and /cheminements-exterieurs/ serve BYTE-IDENTICAL shells (sha e6fbf3f3c030e5c1, 13103 bytes both times) and the word incliné occurs only in the nav. PISTE sandbox 405, bulletin-officiel PDF 404. NOTHING ADMITTED, DELIBERATELY. A rendering of the Légifrance page was obtained through a reader tool and shows Art.2 II 2 a) Profil en long at 5% with tolerances of 8% over <=2 m and 10% over <=0.50 m — which would CONFIRM the prior exactly — but those bytes were never captured, so the figures are NOT filed as values and NOT admitted. Filing them would be a number attached to a quote the corpus cannot check, which is the 2026-08-19 shape. Recorded instead as a code lead naming the document to fetch, per the 2026-08-12 REFERENCE-ONLY ruling.', 0, 'Légifrance publishes consolidated text free. I expect 5% as the general maximum with tolerances at 8% and 10% conditioned on length — i.e. a rise-conditioned structure like the Flemish one, which would make Flanders less of an outlier than it currently looks. No stated basis.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (45, 'accessible-circulation-geometry', 'GB', 'en', 6, 'code', 'intrinsic', 'Approved Document M access to and use of buildings ramp gradient table gov.uk', NULL, 'web', 'scoping', NULL, 9, 9, 1, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'PRIOR CONFIRMED ON BOTH CLAUSES, and the second clause is the one that matters. Table 1 Limits for ramp gradients is exactly the gradient/length table predicted: going 10m -> 1:20 (rise 500mm), 5m -> 1:15 (333mm), 2m -> 1:12 (166mm), with interpolation between 2m and 10m (1:14 at 4m, 1:19 at 9m). BS 8300 appears in the standards list (BS 8300:2001, BS 8300:2009+A1:2010, BS 8300-2:2018) but NO figure in Table 1 is attributed to it, so AD M is recorded as stating its own figure and nothing is inferred about BS 8300 — which is precisely what Leg B row 6 was to test, and it is now testable against a read document rather than a catalogue page. THE SUBSTANTIVE FINDING: the UK does not state a single ceiling, it conditions gradient on the GOING of a flight. 1:12 is UK-legal only for a 2 m going (166 mm of rise, about one step); a 10 m flight is capped at 1:20. So the apparent US/JP/GB agreement at 1:12 is an artefact of reading three differently-shaped rules as one number. Filed as a claim at 1:20 and a condition at 1:12 so the engine cannot gather the false convergence. Payload persisted: 1,471,989-byte PDF, sha256 0e5d4dee25b341f4…, HTTP 200 from gov.uk assets.', 0, 'AD M is Crown copyright and published free, unlike BS 8300 which it references. I expect a gradient/length table (1:20 to 1:12 by flight length) and an explicit pointer to BS 8300 for anything further — which makes AD M the reachable proxy for row 6 paywall, and I must record it as AD M own figure, not as BS 8300.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (46, 'accessible-circulation-geometry', 'JP', 'ja', 1, 'co1', 'intrinsic', 'DPI日本会議 障害者団体 スロープ 勾配 建築物移動等円滑化基準 意見', NULL, 'web', 'scoping', NULL, 9, 9, 1, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'PRIOR HALF RIGHT, AND THE HALF IT GOT WRONG MATTERS. Right: DPI Japan does argue the mandatory standard is insufficient — 特に建物関係はバリアフリー法の義務基準が低く、移動等円滑化基準（義務基準）だけでは円滑な利用ができない, benchmarked against the IPC Accessibility Guide. That is the R7 inadequacy finding the prior expected, admitted as REF-00993 and filed figure_role=finding per the 2026-09-13 ruling. Wrong: the prior assumed a DPO commenting on the GRADIENT. It does not. 勾配, スロープ and 傾斜 occur ZERO times in the retrieved bytes; the worked examples are accessible toilets and parking bays. So the Co-1 leg reached a judgement about the instrument, not about the figure, and the extraction says so in its own notes to stop a later reader over-reading it. The gradient-specific Co-1 claim the prior hoped for was NOT found in this pass and remains owed. R14 on that narrower question: not absence — the query was well formed and returned the DPO, so this is a GENUINE GAP IN WHAT THE DPO HAS PUBLISHED on this parameter, which is itself worth knowing.', 0, 'The natural pairing for row 1: a Japanese DPO commenting on the Japanese statutory figure. I expect a position or consultation response arguing the legal gradient is insufficient — an inadequacy finding under R7 and the 2026-09-13 ruling, not a value. If it states a preferred maximum with its own warrant, that is the batch most valuable admission.');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-17-resea-REF-00993-MOB', 'REF-00993', 'MOB', 'Cross-disability membership of a national DPO; no study sample — this is an organisational position, not a study', NULL, 'PARTIAL', 'PARTIAL, not EXACT, and the reason is the reverse of the usual one. DPI Japan is cross-disability: its assembly speaks for wheelchair users AND for blind, Deaf, intellectually disabled and psychosocially disabled members, so MOB is a PROPER SUBSET of who is speaking, not a proxy standing in for them. The inadequacy claim is made about the mandatory standard as a whole, and the worked examples in the document are toilets and parking bays rather than ramps. So the finding genuinely covers MOB but is not specific to MOB, and grading it EXACT would let a later reader treat a cross-disability judgement as a wheelchair-user-specific one. No sample size: R13 grades population-of-study against population-served, and there is no study here — the warrant is representative standing, not sampling.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'REF-00993', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (132, 'REF-00990', 1, NULL, NULL, NULL, NULL, 1, '内閣（Cabinet of Japan）', NULL, 'author', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (133, 'REF-00991', 1, NULL, NULL, NULL, NULL, 1, '国土交通省（Ministry of Land, Infrastructure, Transport and Tourism）', NULL, 'author', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (134, 'REF-00992', 1, NULL, NULL, NULL, NULL, 1, 'HM Government (Crown copyright)', NULL, 'author', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (135, 'REF-00993', 1, NULL, NULL, NULL, NULL, 1, 'DPI日本会議（DPI-Japan, Japan National Assembly of Disabled Peoples International）', NULL, 'author', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', NULL);
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (9, 'REF-00990', '傾斜路', 'JA', '第十三条・第十九条第二項', '不特定かつ多数の者が利用し、又は主として高齢者、障害者等が利用する傾斜路', 'The statutory Japanese term for ramp. Verbatim and unjudged (D-0173): whether it corresponds to our ramp parameter is judgment stage work, not this.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (10, 'REF-00990', '移動等円滑化経路', 'JA', '第十九条', '高齢者、障害者等が円滑に利用できる経路', 'The accessible-route concept the gradient clause attaches to. The 1:12 ceiling applies to ramps CONSTITUTING this route, not to every ramp in a building — a scoping fact that a bare 1:12 loses.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (11, 'REF-00990', '敷地内の通路', 'JA', '第十七条・第十九条第二項第七号', '不特定かつ多数の者が利用し、又は主として高齢者、障害者等が利用する敷地内の通路', 'Path within the site. Carries its own ramp provisions, and is the domain REF-00989 loosely called outdoors.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (12, 'REF-00991', '誘導すべき建築物特定施設', 'JA', '題名', '高齢者、障害者等が円滑に利用できるようにするために誘導すべき建築物特定施設の構造及び配置に関する基準', 'The 誘導 (guide toward / induce) framing is what distinguishes this instrument from the mandatory 円滑化基準, and it is the distinction REF-00989 collapsed. The source names its own standard as one buildings are GUIDED toward, not held to.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (13, 'REF-00992', 'going of a flight', 'EN', 'Table 1', 'Table 1 Limits for ramp gradients Going of a flight Maximum gradient Maximum rise', 'The UK conditions gradient on the GOING — the horizontal run of one flight. No Japanese or US instrument in this corpus carries this term, and it is why the three 1:12s are not one figure.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (14, 'REF-00993', '義務基準', 'JA', '2．（2）義務基準が不十分', '特に建物関係はバリアフリー法の義務基準が低く、移動等円滑化基準（義務基準）だけでは円滑な利用ができない。', 'The DPO uses 義務基準 (mandatory standard) as a category explicitly contrasted with what adequate access would require. Harvested verbatim; adjudication of whether it maps to our regulatory-floor concept belongs to judgment.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (43, 'REF-00990', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (43, 'REF-00991', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (45, 'REF-00992', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (46, 'REF-00993', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (75, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'IPC Accessibility Guide (International Paralympic Committee)', NULL, 'UNVERIFIED', 4, 0, 'Named by REF-00993 as the benchmark against which Japan mandatory standards are judged LOW, but not retrieved in this pass and therefore not admitted. It is the comparator the Co-1 finding rests on, so admitting the finding without it leaves the standard of comparison unread.', 'HIGH VALUE FOR THE OWNER QUESTION. If the IPC guide states a ramp gradient, it is a T4-class international standard that would clear section 2.3 richness on its own AND would carry the threshold-of-acceptability framing the statutory codes do not. Retrieve before the next determination pass.', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (76, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', '高齢者、障害者等の円滑な移動等に配慮した建築設計標準（国土交通省）', 'https://www.mlit.go.jp/jutakukentiku/content/001402840.pdf', 'UNVERIFIED', 6, 0, 'Surfaced by the row 1 query as an MLIT design standard distinct from both instruments admitted. Not retrieved or screened in this pass; admitting a third Japanese document without reading it would repeat exactly the second-hand-attribution error this batch just corrected.', 'Japan therefore has at least THREE layers on this parameter: mandatory 円滑化基準 (REF-00990), voluntary 誘導基準 (REF-00991), and this design standard. REF-00989 collapsed the first two; this candidate is how the third stops being collapsed as well.', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (77, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'DPI日本会議 — 建築設計標準の見直し＆当事者参画ガイドライン パブリックコメント (2025)', 'https://www.dpi-japan.org/blog/workinggroup/traffic/public-comment-20250430/', 'RESOLVED', 1, 0, 'Retrieved and persisted (HTTP 200) but not screened in depth this pass. Registered rather than dropped because it is a Co-1 consultation response on the very design standard the candidate above names, and it is the most likely home of a gradient-specific DPO position — the thing Leg D looked for and did not find.', 'The gradient-specific Co-1 claim remains OWED after this batch. This candidate is the strongest known route to it.', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00990', 'accessible-circulation-geometry', '9', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', NULL);
