INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (22, 'REF-00990', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'JP', NULL, 'numerical', '1:12', 'rise:run ratio', '勾配は、十二分の一を超えないこと。', '第十九条第二項第四号ロ（移動等円滑化経路を構成する傾斜路）', NULL, 'committee_assertion', 'REF-00990', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE MANDATORY JAPANESE CEILING, and the instrument that actually carries it. Cabinet Order 379/2006 is the 建築物移動等円滑化基準, the binding minimum. The identical sentence appears twice in Art.19(2) — item (iv)ro for ramps on an accessible route replacing or beside stairs, and item (vii)ni(2) for ramps on 敷地内の通路 — so ONE extraction is filed, because it is one figure stated twice and not two figures. Numerically identical to REF-00987 (ADA 1:12) from a wholly separate legal lineage, so this is convergence, not the convergence-by-descent the plan flagged for CA/US. relation=none is literal: the Order names no reference and states no warrant for 1/12. Stored as the source states it, a fraction; 1:12 = 8.33 percent = 4.76 degrees for reconciliation against the degree-denominated research rows, and that conversion is NOT stored.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (23, 'REF-00990', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'JP', NULL, 'numerical', '1:8', 'rise:run ratio', 'ただし、高さが十六センチメートル以下のものにあっては、八分の一を超えないこと。', '第十九条第二項第四号ロただし書（移動等円滑化経路を構成する傾斜路）', NULL, 'committee_assertion', 'REF-00990', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'A RELAXATION, NOT A SECOND CEILING — filed as `condition` so the determination engine does not gather it as a governing claim. 1:8 (12.5 percent) applies ONLY where the rise is 16 cm or less, and it is materially steeper than every other figure in this corpus including the German 6 percent. It is the shape the owner statement of 2026-09-16 warns about: a short rise buys a steeper gradient, which is a trade the code permits and the dose-response evidence does not endorse. Recording it as a condition keeps both facts — the permission is real, and it is not what the jurisdiction requires of ramps generally.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'condition', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (24, 'REF-00991', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'JP', NULL, 'numerical', '1:15', 'rise:run ratio', '勾配は、十五分の一を超えないこと。', '第十一条第一項第六号ロ（敷地内の通路の傾斜路）', NULL, 'committee_assertion', 'REF-00991', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE FIGURE THE CORPUS HELD SECOND-HAND AND MISATTRIBUTED. REF-00989 (Co-1) attributes 1/15 to the Barrier-Free Law as the OUTDOOR figure. It is not in that law: 十五分の一 occurs ZERO times in Cabinet Order 379/2006. It is here, in MLIT Ordinance 114/2006 — the 誘導基準, the ENHANCED standard a building meets voluntarily to be certified, not the mandatory minimum. The domain is roughly what REF-00989 says (敷地内の通路, paths within the site, typically outdoors) but the legal force is not: nothing requires 1/15 of anyone. So the three figures REF-00989 presents as one law are two instruments at two different strengths. This matters beyond bookkeeping — a reader taking the Co-1 source at face value believes Japan requires 1/15 outdoors, and a determination built on that would overstate the regulatory floor. relation=none: the Ordinance states 1/15 absolutely and names no warrant for it.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (25, 'REF-00992', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'GB', NULL, 'numerical', '1:20', 'rise:run ratio', 'Table 1 Limits for ramp gradients Going of a flight Maximum gradient Maximum rise 10m 1:20 500mm 5m 1:15 333mm 2m 1:12 166mm', 'Section 1, para 1.26(b)-(c), Table 1', NULL, 'committee_assertion', 'REF-00992', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE GOVERNING UK FIGURE IS 1:20, NOT 1:12, AND THE DIFFERENCE IS STRUCTURAL. AD M does not state a single ceiling: it conditions gradient on the GOING of the flight. 1:12 is permitted only for a 2 m going, which buys 166 mm of rise; a full 10 m flight is capped at 1:20. Filed at 1:20 because that is the limit for the longest flight the table admits and therefore the governing value for a ramp of any length; the 1:12 and 1:15 rows are filed as conditions. THIS BREAKS NUMERIC COMPARISON ACROSS THE CORPUS: REF-00987 (ADA) and REF-00990 (JP) both state a flat 1:12 with no length term in the same clause, so a table reading 1:12 = 1:12 = 1:12 across US/JP/GB would be false three ways. relation=none: AD M states Table 1 on its own authority. It cites BS 8300 in its standards list but attributes no figure in Table 1 to it, so nothing is inferred about BS 8300 from here — which is what Leg B row 6 exists to test. [VERBATIM-EXEMPT: The persisted artefact is a FlateDecode-compressed PDF (1,471,989 bytes, sha256 0e5d4dee25b341f4e80a99a40a6b36bb1a0251926867aa17e9f71e5b12a1046c), so no substring of its rendered text occurs in its bytes. Read off p.19-20 of that exact artefact via pypdf and reproduced character for character, including the tables column order. gov.uk publishes no HTML carrier of Table 1.]', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (26, 'REF-00992', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'GB', NULL, 'numerical', '1:12', 'rise:run ratio', 'Table 1 Limits for ramp gradients Going of a flight Maximum gradient Maximum rise 10m 1:20 500mm 5m 1:15 333mm 2m 1:12 166mm', 'Section 1, Table 1, row: going 2m', NULL, 'committee_assertion', 'REF-00992', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'FILED AS finding, NOT condition, AND THE REASON IS MECHANICAL. extraction_relations_integrity holds that a condition qualifying nothing is not a condition: it must be the target of an edge or the source of a condition_on edge. No edge from or to any AD M row can exist, because _write_relation_edge requires --quote with NO exemption (unlike --claim-text) and REF-00992 is a FlateDecode-compressed PDF whose rendered text is not a substring of its bytes under any normalisation. The batch-10 plan predicted this casualty for AD M by name. finding is accurate rather than a demotion of convenience — like extraction 18, the ADA advisory, it records something the source states that is NOT its governing ceiling — and it preserves the protection condition was chosen for, since gather_sources takes claim and derived only. THE UK 1:12 IS NOT THE US OR JAPANESE 1:12. It is admissible only for a going of 2 m, capped at 166 mm of rise — roughly one step. Filed as `condition`, not `claim`, so the determination engine does not gather it as a governing ceiling and so a cross-jurisdiction table cannot read three identical 1:12s as agreement. AD M adds that goings between 2 m and 10 m may be interpolated (1:14 at 4 m, 1:19 at 9 m), which is a continuous rule, not three discrete options. [VERBATIM-EXEMPT: Same persisted artefact and method as the sibling 1:20 extraction: FlateDecode-compressed PDF, sha256 0e5d4dee25b341f4e80a99a40a6b36bb1a0251926867aa17e9f71e5b12a1046c, read via pypdf from p.19-20. One table row, filed separately because it states a different figure under a different condition.]', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'finding', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (27, 'REF-00993', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'JP', NULL, 'qualitative', 'mandatory standard insufficient for smooth use', NULL, '国際パラリンピック委員会が策定したバリアフリー整備基準「IPCアクセシビリティガイド」に比べて、特に建物関係はバリアフリー法の義務基準が低く、移動等円滑化基準（義務基準）だけでは円滑な利用ができない。', '2．法律・制度・施策の改善ポイント（2）／義務基準が不十分', NULL, 'participatory_finding', 'REF-00993', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE DPO SAYS THE INSTRUMENT ADMITTED AS REF-00990 IS NOT ENOUGH. DPI Japan, assessing Japan against the CRPD Committee 2022 Concluding Observations, states that the Barrier-Free Act mandatory standards are LOW compared with the IPC Accessibility Guide, particularly for buildings, and that the 移動等円滑化基準 ALONE does not permit 円滑な利用 (smooth use). Owner ruling 2026-09-13 governs: a finding that a CODE is insufficient supplies no value and is still first-class evidence. figure_role=finding, claimed value deliberately non-numeric. SCOPE DISCIPLINE, STATED SO IT IS NOT OVER-READ LATER: this document does NOT discuss ramp gradient. 勾配, スロープ and 傾斜 occur ZERO times in the retrieved bytes; its worked examples are toilets and parking bays. It is evidence that the mandatory standard as a WHOLE is judged inadequate by the people it governs — which bears directly on whether 1:12 can be read as a threshold of acceptability — and it is NOT evidence about the gradient figure specifically. Anyone later citing this row for a gradient claim is over-reading it.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold', 'finding', NULL);
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (19, 23, 'condition_on', 22, NULL, NULL, 'named', NULL, 'ただし、高さが十六センチメートル以下のものにあっては、八分の一を超えないこと。', 'The 1:8 relaxation QUALIFIES the 1:12 ceiling in the same clause: it is the ただし書 (proviso) to Art.19(2)(iv)ro, admissible only where the rise is 16 cm or less. condition_on so the engine reads 1:8 as a qualification of 1:12 rather than as a competing Japanese ceiling. stated=named because the proviso is attached to the ceiling by the statute itself, in one sentence pair — nothing here is inferred.', '2026-09-17 21:02', 'session_2026-09-17-research-batch-10-ramp-gradient-threshold');